# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
I=[['拉丁 ira','愤怒、怒火']]
A=I+[['拉丁 irasci','变得愤怒、发怒']]
W=[E('ire','英 /ˈaɪə/；美 /ˈaɪər/','愤怒；怒火〔正式、文学〕','一句话或一件事，把某人的怒火招了过来。','英语经古法语 ire 借入拉丁 ira“愤怒”。这里讲的是怒火这个名词，不把罕见的其他同形词混入。',I+[['古法语 ire → 中古英语及现代英语 ire','愤怒、怒火']],'常见写法不是直接说“他很 ire”，而是说某事引起了某人的 ire。新闻或评论用这个词，通常是在点出谁被惹怒了；日常口语用 anger 更自然。','arouse/provoke/draw the ire of somebody；direct one’s ire at somebody/something。一般用作不可数名词。','angry 是形容词，可以说 he is angry；ire 是名词。anger 语域普通，ire 带有较明显的书面色彩。',('The sudden price increase drew the ire of regular customers.','突然涨价惹怒了老顾客。'),('The critic directed her ire at the project’s poor planning.','这位评论家把怒火指向项目糟糕的规划。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/ire','https://www.etymonline.com/word/ire']),
E('irate','/aɪˈreɪt/；美亦 /ˈaɪreɪt/','大怒的；怒气冲冲的','人正在气头上，话里或行动里都带着怒气。','独立借拉丁 iratus“发怒的”，它是 irasci“发怒”的分词形式。现代可以把它与 ire 配成一组，但历史上不是英语 ire 临时加 -ate 造出的。',A+[['拉丁 iratus → 英语 irate','发怒的 → 怒气冲冲的']],'An irate caller 是一个打来电话、正在生气的人。这个词描写当时的状态，并不能单凭这一次生气，就说这个人一贯脾气很坏。','an irate customer/passenger/caller；irate about/over something。','irate 是已经发怒；irascible 是容易发怒的性情。一个平时温和的人，也可能因为被重复收费而变得 irate。',('An irate passenger demanded to know why the flight had been cancelled.','一名怒气冲冲的乘客要求解释航班为什么取消。'),('She sent an irate email after being charged twice for the same order.','同一订单被扣了两次钱后，她发了一封愤怒的邮件。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/irate','https://www.etymonline.com/word/irate']),
E('irascible','/ɪˈræsəbəl/','易怒的；脾气暴躁的〔正式〕','像一点就着的火，稍受刺激就容易发脾气。','晚期拉丁 irascibilis 来自 irasci“发怒”，经法语或直接拉丁借入英语。irasc- 是历史动词词干，-ible 表示这种倾向；不必把里面的 sc 再拆成一个英语词根。',A+[['晚期拉丁 irascibilis','容易发怒的'],['法语 irascible／直接拉丁借入 → 英语 irascible','易怒、脾气暴躁的']],'它多用来写人的脾气：不是今天偶尔生气，而是有一点不顺心就容易动怒。文学人物即使同时慷慨、可靠，也仍可能是 irascible，几个性格特点可以并存。','an irascible person；an irascible temperament；an irascible old man。','irritable 可以是因为累了、饿了而一时烦躁；irascible 更常描述容易动怒的性格，语气也更书面。',('The irascible editor snapped at anyone who interrupted him.','这位脾气暴躁的编辑对每个打断他的人都厉声呵斥。'),('The novel’s irascible landlord is surprisingly generous to his neighbours.','小说里那个易怒的房东，对邻居却出人意料地大方。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/irascible','https://www.etymonline.com/word/irascible'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C0612');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C0612');keep={w['word']for w in W};excluded={w:'按用户当前范围暂略：罕见派生词或不属于本页怒火义的同形词。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C0612',meaning='愤怒；发怒',core='先记 ira 是怒火，irasci 是人发起怒来。',image='怒火本身是 ire；人已经怒气冲冲是 irate；性情一点就着是 irascible。',intro='这组词不多，重点是分清“情绪、当下状态、性格倾向”。它们大多偏书面，日常可先与 anger、angry 对照。',forms='拉丁 ira“愤怒” → irasci“发怒” → iratus“发怒的”；irasc- 与 irat- 是相关的历史形式。',branches=[['怒火','ire'],['已经发怒','irate'],['容易发怒','irascible']],contrasts='ire 不能当形容词使用；irate 与 irascible 也不能简单互换，一个描写当前怒气，一个强调易怒倾向。',practice='用 irate 描写一次投诉中的顾客，再用 irascible 描写某个角色一贯的脾气。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/ire','https://www.etymonline.com/word/irate','https://www.etymonline.com/word/irascible'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_217_irasc.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0612',len(W),'new')
